11	 * keyed on {@code (lastName, postcode)} via a deterministic {@code householdId} (see
12	 * {@link OwnerHousehold}), owners sharing a lastName and postcode are the same household: a
13	 * second such owner is a household duplicate and is rejected 409 via
14	 * {@link DuplicateHouseholdException}.
15	 *
16	 * <p>{@code sharesHousehold} bypasses this block: a declared household member is allowed to be
17	 * created (and is not flagged as a possible duplicate downstream — see
18	 * {@link AssignPossibleDuplicate}). Runs after the householdId is assigned and before the owner
19	 * is saved.
20	 */
21	public class EnsureUniqueOwnerIdentity {
22	
23	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws DuplicateHouseholdException {
25	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
26	            return; // declared household member bypasses the duplicate block
27	        }
28	        String householdId = owner.getHouseholdId();
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (householdId.equals(existing.getHouseholdId())) {
31	                throw new DuplicateHouseholdException(householdId);
32	            }
33	        }
34	    }
