1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.model.OwnerTelephones;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Assigns the owner's soft-duplicate flags. Runs after {@link EnsureUniqueOwnerIdentity}
11	 * has already rejected household duplicates, so any match here is a genuinely different
12	 * owner. A soft (possible) duplicate is an existing owner that shares this owner's
13	 * {@code lastName} (case-insensitive) and {@code postcode} but has a different (normalized)
14	 * telephone. When one exists the owner is still created, with {@code possibleDuplicate} true
15	 * and {@code possibleDuplicateOf} set to the matching owner's id; otherwise
16	 * {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is null. The earliest
17	 * (smallest id) match is chosen so the result is deterministic.
18	 *
19	 * <p>A declared household member ({@code sharesHousehold} true) is never flagged: it was
20	 * created deliberately as part of the household, so it is not a suspected duplicate.
21	 */
22	public class AssignPossibleDuplicate {
23	
24	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
25	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
26	            owner.setPossibleDuplicate(false);
27	            owner.setPossibleDuplicateOf(null);
28	            return;
29	        }
30	
31	        String lastName = owner.getLastName();
32	        String postcode = owner.getPostcode();
33	        String telephone = OwnerTelephones.toE164OrRaw(owner.getTelephone());
34	
35	        Owner match = null;
36	        if (lastName != null && postcode != null) {
37	            for (Owner existing : ownerRepository.findAll()) {
38	                if (existing.getId() == null || existing.getId().equals(owner.getId())) {
39	                    continue;
40	                }
41	                if (lastName.equalsIgnoreCase(existing.getLastName())
42	                        && postcode.equals(existing.getPostcode())
43	                        && !telephone.equals(OwnerTelephones.toE164OrRaw(existing.getTelephone()))) {
44	                    if (match == null || existing.getId() < match.getId()) {
45	                        match = existing;
46	                    }
47	                }
48	            }
49	        }
50	
51	        if (match != null) {
